package document

import (
	"github.com/TrebuchetDynamics/gormes-agent/internal/extensibility/skills/document/model"
	"github.com/TrebuchetDynamics/gormes-agent/internal/extensibility/skills/document/parsing"
	"github.com/TrebuchetDynamics/gormes-agent/internal/extensibility/skills/document/rendering"
	"github.com/TrebuchetDynamics/gormes-agent/internal/extensibility/skills/document/validation"
)

const (
	DefaultMaxDocumentBytes = model.DefaultMaxDocumentBytes
	DefaultSelectionCap     = model.DefaultSelectionCap
)

// Skill is the typed in-memory representation of one SKILL.md artifact.
type Skill = model.Skill

type CredentialGroup = model.CredentialGroup

type SkillConditions = model.SkillConditions

// SkillValidationCode classifies a malformed SKILL.md frontmatter problem.
// The stable code vocabulary lets callers report frontmatter defects without
// depending on parser-specific error strings.
type SkillValidationCode = validation.SkillValidationCode

const (
	SkillValidationMissingOpen      SkillValidationCode = validation.SkillValidationMissingOpen
	SkillValidationMissingClose     SkillValidationCode = validation.SkillValidationMissingClose
	SkillValidationEmptyFrontmatter SkillValidationCode = validation.SkillValidationEmptyFrontmatter
	SkillValidationYAMLParse        SkillValidationCode = validation.SkillValidationYAMLParse
	SkillValidationNullBytes        SkillValidationCode = validation.SkillValidationNullBytes
	SkillValidationNestedQuotes     SkillValidationCode = validation.SkillValidationNestedQuotes
	SkillValidationSlugMismatch     SkillValidationCode = validation.SkillValidationSlugMismatch
)

// SkillValidationError carries a single classified frontmatter defect with
// optional 1-based line evidence so callers can surface a useful pointer
// without parsing the file twice.
type SkillValidationError = validation.SkillValidationError

// FrontmatterValidateOptions opts a SKILL.md document into the more
// expensive cross-checks. SLUG_MISMATCH only fires when ExpectedSlug is set.
type FrontmatterValidateOptions = validation.FrontmatterValidateOptions

// Parse converts a SKILL.md document into a typed Skill.
func Parse(raw []byte, maxBytes int) (Skill, error) {
	return parsing.Parse(raw, maxBytes)
}

func RenderBlock(skills []Skill) string {
	return rendering.RenderBlock(skills)
}

func RenderDocument(skill Skill) string {
	return rendering.RenderDocument(skill)
}

// ValidateSkillFrontmatter inspects raw SKILL.md bytes for the seven
// frontmatter validation classes that a forgiving YAML parser silently
// accepts. Returns nil when the document is well-formed.
func ValidateSkillFrontmatter(raw []byte, opts FrontmatterValidateOptions) []SkillValidationError {
	return validation.ValidateSkillFrontmatter(raw, opts)
}

package model

import (
	"fmt"
	"strings"
)

const (
	DefaultMaxDocumentBytes = 128 * 1024
	DefaultSelectionCap     = 3
)

// Skill is the typed in-memory representation of one SKILL.md artifact.
type Skill struct {
	Name        string
	Description string
	Body        string
	Path        string
	RawBytes    int

	Version        string
	Author         string
	License        string
	HermesTags     []string
	HermesCategory string
	HermesHomepage string
	RelatedSkills  []string

	Platforms        []string
	RequiredEnvVars  []string
	CredentialGroups []CredentialGroup
	Triggers         []string
	Exclusions       []string
	ReviewState      string
	Conditions       SkillConditions
}

type CredentialGroup struct {
	AnyOf []string
}

type SkillConditions struct {
	FallbackForTools    []string
	FallbackForToolsets []string
	RequiresTools       []string
	RequiresToolsets    []string
}

// Validate enforces the minimal Phase 2.G0 contract for a parsed skill.
func (s Skill) Validate(maxBytes int) error {
	if strings.TrimSpace(s.Name) == "" {
		return fmt.Errorf("skill name is required")
	}
	if strings.TrimSpace(s.Description) == "" {
		return fmt.Errorf("skill description is required")
	}
	if strings.TrimSpace(s.Body) == "" {
		return fmt.Errorf("skill body is required")
	}

	size := s.RawBytes
	if size == 0 {
		size = len(s.Name) + len(s.Description) + len(s.Body)
	}
	if maxBytes > 0 && size > maxBytes {
		return fmt.Errorf("skill document too large: %d > %d bytes", size, maxBytes)
	}
	return nil
}

package parsing

import (
	"fmt"
	"strings"

	"github.com/TrebuchetDynamics/gormes-agent/internal/extensibility/skills/document/model"
	"github.com/TrebuchetDynamics/gormes-agent/internal/extensibility/skills/document/structure"

	"gopkg.in/yaml.v3"
)

// Parse converts a SKILL.md document into a typed model.Skill.
func Parse(raw []byte, maxBytes int) (model.Skill, error) {
	doc := structure.NormalizeBytes(raw)
	if maxBytes > 0 && len(raw) > maxBytes {
		return model.Skill{}, fmt.Errorf("skill document too large: %d > %d bytes", len(raw), maxBytes)
	}

	lines := structure.SplitLines(doc)
	if len(lines) == 0 || !structure.IsFrontmatterDelimiter(lines[0]) {
		return model.Skill{}, fmt.Errorf("skill frontmatter must start with ---")
	}

	end := -1
	for i := 1; i < len(lines); i++ {
		if structure.IsFrontmatterDelimiter(lines[i]) {
			end = i
			break
		}
	}
	if end == -1 {
		return model.Skill{}, fmt.Errorf("skill frontmatter closing --- not found")
	}

	var skill model.Skill
	skill.RawBytes = len(raw)

	frontmatter := parseFrontmatter(strings.Join(lines[1:end], "\n"))
	skill.Name = frontmatterString(frontmatter, "name")
	skill.Description = frontmatterString(frontmatter, "description")
	skill.Version = frontmatterString(frontmatter, "version")
	skill.Author = frontmatterString(frontmatter, "author")
	skill.License = frontmatterString(frontmatter, "license")
	skill.HermesTags = hermesTags(frontmatter)
	skill.HermesCategory = hermesMetadataString(frontmatter, "category")
	skill.HermesHomepage = hermesMetadataString(frontmatter, "homepage")
	skill.RelatedSkills = relatedSkills(frontmatter)
	skill.Platforms = frontmatterStringList(frontmatter["platforms"])
	skill.RequiredEnvVars = requiredEnvVars(frontmatter)
	skill.CredentialGroups = credentialGroups(frontmatter)
	skill.Triggers = frontmatterStringList(frontmatter["triggers"])
	skill.Exclusions = frontmatterStringList(frontmatter["exclusions"])
	skill.ReviewState = reviewState(frontmatter)
	skill.Conditions = skillConditions(frontmatter)

	skill.Body = strings.Trim(strings.Join(lines[end+1:], "\n"), "\n")
	if err := skill.Validate(maxBytes); err != nil {
		return model.Skill{}, err
	}
	return skill, nil
}

func trimScalar(value string) string {
	value = strings.TrimSpace(value)
	if len(value) >= 2 {
		if value[0] == '"' && value[len(value)-1] == '"' {
			return value[1 : len(value)-1]
		}
		if value[0] == '\'' && value[len(value)-1] == '\'' {
			return value[1 : len(value)-1]
		}
	}
	return value
}

func parseFrontmatter(raw string) map[string]any {
	out := map[string]any{}
	if strings.TrimSpace(raw) == "" {
		return out
	}
	if err := yaml.Unmarshal([]byte(raw), &out); err == nil {
		return out
	}

	for _, line := range strings.Split(raw, "\n") {
		if line == "" || line[0] == ' ' || line[0] == '\t' {
			continue
		}
		key, value, ok := strings.Cut(line, ":")
		if !ok {
			continue
		}
		out[strings.TrimSpace(key)] = trimScalar(value)
	}
	return out
}

func frontmatterString(frontmatter map[string]any, key string) string {
	value, ok := frontmatter[key]
	if !ok || value == nil {
		return ""
	}
	return strings.TrimSpace(fmt.Sprint(value))
}

func frontmatterStringList(value any) []string {
	switch v := value.(type) {
	case nil:
		return nil
	case []any:
		out := make([]string, 0, len(v))
		for _, item := range v {
			out = appendStringValue(out, item)
		}
		return dedupeStrings(out)
	case []string:
		return dedupeStrings(v)
	case string:
		return parseInlineStringList(v)
	default:
		return appendStringValue(nil, v)
	}
}

func requiredEnvVars(frontmatter map[string]any) []string {
	var out []string
	out = append(out, frontmatterStringList(frontmatter["required_environment_variables"])...)
	if prereqs, ok := frontmatter["prerequisites"].(map[string]any); ok {
		out = append(out, frontmatterStringList(prereqs["env_vars"])...)
	}
	return dedupeStrings(out)
}

func credentialGroups(frontmatter map[string]any) []model.CredentialGroup {
	var out []model.CredentialGroup
	out = append(out, parseCredentialGroups(frontmatter["credential_groups"])...)
	out = append(out, parseCredentialGroups(frontmatter["required_environment_variable_groups"])...)
	if prereqs, ok := frontmatter["prerequisites"].(map[string]any); ok {
		out = append(out, parseCredentialGroups(prereqs["credential_groups"])...)
		out = append(out, parseCredentialGroups(prereqs["env_var_groups"])...)
	}
	return dedupeCredentialGroups(out)
}

func parseCredentialGroups(value any) []model.CredentialGroup {
	switch v := value.(type) {
	case nil:
		return nil
	case []any:
		out := make([]model.CredentialGroup, 0, len(v))
		for _, item := range v {
			if group, ok := parseCredentialGroup(item); ok {
				out = append(out, group)
			}
		}
		return out
	case []string, string:
		if group, ok := parseCredentialGroup(v); ok {
			return []model.CredentialGroup{group}
		}
		return nil
	default:
		if group, ok := parseCredentialGroup(v); ok {
			return []model.CredentialGroup{group}
		}
		return nil
	}
}

func parseCredentialGroup(value any) (model.CredentialGroup, bool) {
	switch v := value.(type) {
	case map[string]any:
		names := frontmatterStringList(v["any_of"])
		if len(names) == 0 {
			names = frontmatterStringList(v["anyOf"])
		}
		if len(names) == 0 {
			names = frontmatterStringList(v["env_vars"])
		}
		names = dedupeStrings(names)
		return model.CredentialGroup{AnyOf: names}, len(names) > 0
	case []any, []string, string:
		names := dedupeStrings(frontmatterStringList(v))
		return model.CredentialGroup{AnyOf: names}, len(names) > 0
	default:
		return model.CredentialGroup{}, false
	}
}

func dedupeCredentialGroups(in []model.CredentialGroup) []model.CredentialGroup {
	if len(in) == 0 {
		return nil
	}
	out := make([]model.CredentialGroup, 0, len(in))
	seen := map[string]bool{}
	for _, group := range in {
		group.AnyOf = dedupeStrings(group.AnyOf)
		if len(group.AnyOf) == 0 {
			continue
		}
		key := strings.Join(group.AnyOf, "\x00")
		if seen[key] {
			continue
		}
		seen[key] = true
		out = append(out, group)
	}
	return out
}

// hermesTags collects tag strings from the upstream-supported locations:
// nested `metadata.hermes.tags` (claude-design, design-md), bare `hermes.tags`
// (legacy), and a flat top-level `tags` list (popular-web-designs).
func hermesTags(frontmatter map[string]any) []string {
	var out []string
	if metadata, ok := frontmatter["metadata"].(map[string]any); ok {
		if hermes, ok := metadata["hermes"].(map[string]any); ok {
			out = append(out, frontmatterStringList(hermes["tags"])...)
		}
	}
	if hermes, ok := frontmatter["hermes"].(map[string]any); ok {
		out = append(out, frontmatterStringList(hermes["tags"])...)
	}
	out = append(out, frontmatterStringList(frontmatter["tags"])...)
	return dedupeStrings(out)
}

// relatedSkills mirrors hermesTags' precedence for the related_skills field
// so creative skills carry cross-reference routing without inflating the
// top-level frontmatter shape.
func relatedSkills(frontmatter map[string]any) []string {
	var out []string
	if metadata, ok := frontmatter["metadata"].(map[string]any); ok {
		if hermes, ok := metadata["hermes"].(map[string]any); ok {
			out = append(out, frontmatterStringList(hermes["related_skills"])...)
		}
	}
	if hermes, ok := frontmatter["hermes"].(map[string]any); ok {
		out = append(out, frontmatterStringList(hermes["related_skills"])...)
	}
	out = append(out, frontmatterStringList(frontmatter["related_skills"])...)
	return dedupeStrings(out)
}

func hermesMetadataString(frontmatter map[string]any, key string) string {
	if value := frontmatterString(hermesMetadata(frontmatter), key); value != "" {
		return value
	}
	return frontmatterString(frontmatter, key)
}

func reviewState(frontmatter map[string]any) string {
	if state := frontmatterString(frontmatter, "review_state"); state != "" {
		return state
	}
	if review, ok := frontmatter["review"].(map[string]any); ok {
		return frontmatterString(review, "state")
	}
	return ""
}

func skillConditions(frontmatter map[string]any) model.SkillConditions {
	hermes := hermesMetadata(frontmatter)
	return model.SkillConditions{
		FallbackForTools:    dedupeStrings(frontmatterStringList(hermes["fallback_for_tools"])),
		FallbackForToolsets: dedupeStrings(frontmatterStringList(hermes["fallback_for_toolsets"])),
		RequiresTools:       dedupeStrings(frontmatterStringList(hermes["requires_tools"])),
		RequiresToolsets:    dedupeStrings(frontmatterStringList(hermes["requires_toolsets"])),
	}
}

func hermesMetadata(frontmatter map[string]any) map[string]any {
	if metadata, ok := frontmatter["metadata"].(map[string]any); ok {
		if hermes, ok := metadata["hermes"].(map[string]any); ok {
			return hermes
		}
	}
	if hermes, ok := frontmatter["hermes"].(map[string]any); ok {
		return hermes
	}
	return nil
}

func appendStringValue(out []string, value any) []string {
	switch v := value.(type) {
	case nil:
		return out
	case map[string]any:
		if name := frontmatterString(v, "name"); name != "" {
			return append(out, name)
		}
		if envVar := frontmatterString(v, "env_var"); envVar != "" {
			return append(out, envVar)
		}
		return out
	default:
		if s := strings.TrimSpace(fmt.Sprint(v)); s != "" {
			return append(out, s)
		}
		return out
	}
}

func parseInlineStringList(raw string) []string {
	raw = strings.TrimSpace(raw)
	raw = strings.TrimPrefix(raw, "[")
	raw = strings.TrimSuffix(raw, "]")
	if raw == "" {
		return nil
	}
	parts := strings.Split(raw, ",")
	out := make([]string, 0, len(parts))
	for _, part := range parts {
		part = strings.Trim(strings.TrimSpace(part), "\"'")
		if part != "" {
			out = append(out, part)
		}
	}
	return dedupeStrings(out)
}

func dedupeStrings(in []string) []string {
	if len(in) == 0 {
		return nil
	}
	seen := map[string]bool{}
	out := make([]string, 0, len(in))
	for _, value := range in {
		value = strings.TrimSpace(value)
		if value == "" || seen[value] {
			continue
		}
		seen[value] = true
		out = append(out, value)
	}
	return out
}

package validation

import (
	"fmt"
	"regexp"
	"strings"

	"github.com/TrebuchetDynamics/gormes-agent/internal/extensibility/skills/document/structure"

	"gopkg.in/yaml.v3"
)

// SkillValidationCode classifies a malformed SKILL.md frontmatter problem.
// The stable code vocabulary lets callers report frontmatter defects without
// depending on parser-specific error strings.
type SkillValidationCode string

const (
	SkillValidationMissingOpen      SkillValidationCode = "MISSING_OPEN"
	SkillValidationMissingClose     SkillValidationCode = "MISSING_CLOSE"
	SkillValidationEmptyFrontmatter SkillValidationCode = "EMPTY_FRONTMATTER"
	SkillValidationYAMLParse        SkillValidationCode = "YAML_PARSE"
	SkillValidationNullBytes        SkillValidationCode = "NULL_BYTES"
	SkillValidationNestedQuotes     SkillValidationCode = "NESTED_QUOTES"
	SkillValidationSlugMismatch     SkillValidationCode = "SLUG_MISMATCH"
)

// SkillValidationError carries a single classified frontmatter defect with
// optional 1-based line evidence so callers can surface a useful pointer
// without parsing the file twice.
type SkillValidationError struct {
	Code    SkillValidationCode
	Message string
	Line    int
}

// FrontmatterValidateOptions opts a SKILL.md document into the more
// expensive cross-checks. SLUG_MISMATCH only fires when ExpectedSlug is set.
type FrontmatterValidateOptions struct {
	ExpectedSlug string
}

var (
	frontmatterKeyValuePattern = regexp.MustCompile(`^\s*[A-Za-z_][\w-]*\s*:\s*(.*)$`)
	headingPattern             = regexp.MustCompile(`^#{1,6}\s`)
)

// ValidateSkillFrontmatter inspects raw SKILL.md bytes for the seven
// frontmatter validation classes that a forgiving YAML parser silently
// accepts. Returns nil when the document is well-formed.
//
// Order of checks is deliberate: cheap byte-level (NULL_BYTES) first, then
// structural (MISSING_OPEN, MISSING_CLOSE, EMPTY_FRONTMATTER), then
// value-shape (NESTED_QUOTES), then YAML parse, then slug cross-check.
func ValidateSkillFrontmatter(raw []byte, opts FrontmatterValidateOptions) []SkillValidationError {
	content := structure.NormalizeBytes(raw)

	var errs []SkillValidationError

	if idx := strings.IndexByte(content, 0); idx >= 0 {
		line := strings.Count(content[:idx], "\n") + 1
		errs = append(errs, SkillValidationError{
			Code:    SkillValidationNullBytes,
			Message: "content contains null bytes (likely binary corruption)",
			Line:    line,
		})
	}

	lines := structure.SplitLines(content)
	firstNonEmpty := -1
	for i, line := range lines {
		if strings.TrimSpace(line) != "" {
			firstNonEmpty = i
			break
		}
	}
	if firstNonEmpty == -1 {
		errs = append(errs, SkillValidationError{
			Code:    SkillValidationMissingOpen,
			Message: "file is empty or whitespace-only; expected frontmatter starting with ---",
			Line:    1,
		})
		return errs
	}
	if !structure.IsFrontmatterDelimiter(lines[firstNonEmpty]) {
		errs = append(errs, SkillValidationError{
			Code:    SkillValidationMissingOpen,
			Message: "frontmatter must start with --- on the first non-empty line",
			Line:    firstNonEmpty + 1,
		})
		return errs
	}

	closeLine := -1
	headingBeforeClose := -1
	for i := firstNonEmpty + 1; i < len(lines); i++ {
		trimmed := strings.TrimSpace(lines[i])
		if structure.IsFrontmatterDelimiter(trimmed) {
			closeLine = i
			break
		}
		if headingBeforeClose == -1 && headingPattern.MatchString(trimmed) {
			headingBeforeClose = i
		}
	}
	if closeLine == -1 {
		message := "no closing --- delimiter found"
		evidenceLine := firstNonEmpty + 1
		if headingBeforeClose >= 0 {
			message = fmt.Sprintf("no closing --- before heading at line %d", headingBeforeClose+1)
			evidenceLine = headingBeforeClose + 1
		}
		errs = append(errs, SkillValidationError{
			Code:    SkillValidationMissingClose,
			Message: message,
			Line:    evidenceLine,
		})
		return errs
	}
	if headingBeforeClose >= 0 && headingBeforeClose < closeLine {
		errs = append(errs, SkillValidationError{
			Code:    SkillValidationMissingClose,
			Message: fmt.Sprintf("heading at line %d found inside frontmatter zone (closing --- comes after)", headingBeforeClose+1),
			Line:    headingBeforeClose + 1,
		})
	}

	frontmatterLines := lines[firstNonEmpty+1 : closeLine]
	frontmatterBody := strings.Join(frontmatterLines, "\n")
	if strings.TrimSpace(frontmatterBody) == "" {
		errs = append(errs, SkillValidationError{
			Code:    SkillValidationEmptyFrontmatter,
			Message: "frontmatter block is empty",
			Line:    firstNonEmpty + 1,
		})
	}

	for offset, line := range frontmatterLines {
		match := frontmatterKeyValuePattern.FindStringSubmatch(line)
		if match == nil {
			continue
		}
		if countUnescapedDoubleQuotes(match[1]) >= 3 {
			errs = append(errs, SkillValidationError{
				Code:    SkillValidationNestedQuotes,
				Message: "nested double quotes in YAML value (use single quotes for the outer)",
				Line:    firstNonEmpty + 1 + offset + 1,
			})
		}
	}

	if strings.TrimSpace(frontmatterBody) != "" {
		var probe map[string]any
		if err := yaml.Unmarshal([]byte(frontmatterBody), &probe); err != nil {
			errs = append(errs, SkillValidationError{
				Code:    SkillValidationYAMLParse,
				Message: "yaml parse failed: " + err.Error(),
				Line:    firstNonEmpty + 1,
			})
		} else if expected := strings.TrimSpace(opts.ExpectedSlug); expected != "" {
			if declared, ok := probe["slug"].(string); ok {
				if strings.TrimSpace(declared) != expected {
					errs = append(errs, SkillValidationError{
						Code:    SkillValidationSlugMismatch,
						Message: fmt.Sprintf("frontmatter slug %q does not match path-derived slug %q", declared, expected),
						Line:    firstNonEmpty + 1,
					})
				}
			}
		}
	}

	return errs
}

func countUnescapedDoubleQuotes(value string) int {
	count := 0
	for i := 0; i < len(value); i++ {
		if value[i] != '"' {
			continue
		}
		if i > 0 && value[i-1] == '\\' {
			continue
		}
		count++
	}
	return count
}

package structure

import "strings"

// NormalizeBytes applies the byte-to-document normalization shared by parsing
// and frontmatter validation before they inspect SKILL.md delimiters.
func NormalizeBytes(raw []byte) string {
	content := string(raw)
	content = strings.TrimPrefix(content, "\uFEFF")
	content = strings.ReplaceAll(content, "\r\n", "\n")
	return content
}

// SplitLines keeps delimiter scanning consistent across document consumers.
func SplitLines(content string) []string {
	return strings.Split(content, "\n")
}

// IsFrontmatterDelimiter applies the shared SKILL.md delimiter policy used by
// parsers and validators before they inspect document sections.
func IsFrontmatterDelimiter(line string) bool {
	return strings.TrimSpace(line) == "---"
}

package rendering

import (
	"github.com/TrebuchetDynamics/gormes-agent/internal/extensibility/skills/document/model"

	"strconv"
	"strings"
)

func RenderBlock(skills []model.Skill) string {
	if len(skills) == 0 {
		return ""
	}

	var b strings.Builder
	b.WriteString("<skills>\n")
	for i, skill := range skills {
		if i > 0 {
			b.WriteByte('\n')
		}
		b.WriteString("## ")
		b.WriteString(skill.Name)
		b.WriteByte('\n')
		b.WriteString(skill.Description)
		b.WriteString("\n\n")
		b.WriteString(skill.Body)
		b.WriteByte('\n')
	}
	b.WriteString("</skills>")
	return b.String()
}

func RenderDocument(skill model.Skill) string {
	var b strings.Builder
	b.WriteString("---\n")
	b.WriteString("name: ")
	b.WriteString(strconv.Quote(strings.TrimSpace(skill.Name)))
	b.WriteByte('\n')
	b.WriteString("description: ")
	b.WriteString(strconv.Quote(strings.TrimSpace(skill.Description)))
	b.WriteString("\n---\n\n")
	b.WriteString(strings.TrimSpace(skill.Body))
	b.WriteByte('\n')
	return b.String()
}

package skills

import (
	"context"
	"os"
	"path/filepath"
	"strings"
	"testing"
)

const claudeDesignFrontmatter = `---
name: claude-design
description: Design one-off HTML artifacts (landing, deck, prototype).
version: 1.0.0
author: BadTechBandit
license: MIT
metadata:
  hermes:
    tags: [design, html, prototype, ux, ui, creative, artifact, deck, motion, design-system]
    related_skills: [design-md, popular-web-designs, excalidraw, architecture-diagram]
---

# Claude Design for CLI/API Agents

Use this skill when the user asks for design work in a CLI/API environment.
`

const popularWebDesignsFrontmatter = `---
name: popular-web-designs
