func TestCreativeSkillMetadata_ParsesClaudeDesignFrontmatter(t *testing.T) {
	skill, err := Parse([]byte(claudeDesignFrontmatter), 16*1024)
	if err != nil {
		t.Fatalf("Parse error = %v", err)
	}

	if skill.Name != "claude-design" {
		t.Fatalf("Name = %q, want claude-design", skill.Name)
	}
	if skill.Description != "Design one-off HTML artifacts (landing, deck, prototype)." {
		t.Fatalf("Description = %q", skill.Description)
	}
	if got := len(skill.Description); got > 60 {
		t.Fatalf("Description length = %d, want <= 60 chars", got)
	}
	if skill.Version != "1.0.0" {
		t.Fatalf("Version = %q, want 1.0.0", skill.Version)
	}
	if skill.Author != "BadTechBandit" {
		t.Fatalf("Author = %q, want BadTechBandit", skill.Author)
	}
	if skill.License != "MIT" {
		t.Fatalf("License = %q, want MIT", skill.License)
	}
	if !containsAllStrings(skill.HermesTags, []string{"design", "html", "prototype", "design-system"}) {
		t.Fatalf("HermesTags = %v, missing expected design tags", skill.HermesTags)
	}
	if !containsAllStrings(skill.RelatedSkills, []string{"design-md", "popular-web-designs"}) {
		t.Fatalf("RelatedSkills = %v, missing related design skills", skill.RelatedSkills)
	}
}

func TestCreativeSkillMetadata_DistinguishesDesignRoutes(t *testing.T) {
	root := t.TempDir()
	writeRawSkill(t, filepath.Join(root, "active", "claude-design", "SKILL.md"), claudeDesignFrontmatter)
	writeRawSkill(t, filepath.Join(root, "active", "popular-web-designs", "SKILL.md"), popularWebDesignsFrontmatter)
	writeRawSkill(t, filepath.Join(root, "active", "design-md", "SKILL.md"), designMdFrontmatter)

	runtime := NewRuntime(root, 16*1024, 1, "")

	cases := []struct {
		name  string
		query string
		want  string
	}{
		{"prototype request routes to claude-design", "design a one-off HTML prototype deck artifact", "claude-design"},
		{"stripe lookalike routes to popular-web-designs", "make it look like stripe with the linear typography", "popular-web-designs"},
		{"DESIGN.md spec routes to design-md", "author a Google DESIGN.md token spec with WCAG checks", "design-md"},
	}

	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			_, names, _, err := runtime.BuildSkillBlockWithOptions(context.Background(), tc.query, RuntimeOptions{})
			if err != nil {
				t.Fatalf("BuildSkillBlockWithOptions error = %v", err)
			}
			if len(names) != 1 {
				t.Fatalf("names = %v, want exactly one route for query %q", names, tc.query)
			}
			if names[0] != tc.want {
				t.Fatalf("query %q routed to %q, want %q (skills must remain distinct, not collapsed)", tc.query, names[0], tc.want)
			}
		})
	}
}

func TestCreativeSkillMetadata_InvalidDraftExcluded(t *testing.T) {
	root := t.TempDir()
	writeRawSkill(t, filepath.Join(root, "active", "claude-design", "SKILL.md"), claudeDesignFrontmatter)

	draftDir := filepath.Join(root, "active", "draft-design")
	if err := os.MkdirAll(draftDir, 0o755); err != nil {
		t.Fatalf("MkdirAll: %v", err)
	}
	missingClose := strings.Join([]string{
		"---",
		"name: draft-design",
		"description: half-written draft",
		"# stray heading",
		"",
		"body",
	}, "\n")
	if err := os.WriteFile(filepath.Join(draftDir, "SKILL.md"), []byte(missingClose), 0o644); err != nil {
		t.Fatalf("WriteFile: %v", err)
	}

	runtime := NewRuntime(root, 16*1024, 5, "")
	block, names, statuses, err := runtime.BuildSkillBlockWithOptions(context.Background(), "design", RuntimeOptions{})
	if err != nil {
		t.Fatalf("BuildSkillBlockWithOptions error = %v", err)
	}
	if strings.Contains(block, "draft-design") {
		t.Fatalf("rendered block leaks invalid draft: %q", block)
	}
	for _, n := range names {
		if n == "draft-design" {
			t.Fatalf("names = %v, must not include invalid draft", names)
		}
	}
	if !anyStatusCode(statuses, SkillStatusFrontmatterInvalid) {
		t.Fatalf("statuses = %+v, want one SkillStatusFrontmatterInvalid for the draft", statuses)
	}
}

func writeRawSkill(t *testing.T, path, content string) {
	t.Helper()
	if err := os.MkdirAll(filepath.Dir(path), 0o755); err != nil {
		t.Fatalf("MkdirAll(%q): %v", filepath.Dir(path), err)
	}
	if err := os.WriteFile(path, []byte(content), 0o644); err != nil {
		t.Fatalf("WriteFile(%q): %v", path, err)
	}
}

func containsAllStrings(haystack, needles []string) bool {
	have := map[string]bool{}
	for _, value := range haystack {
		have[value] = true
	}
	for _, want := range needles {
		if !have[want] {
			return false
		}
	}
	return true
}

func anyStatusCode(statuses []SkillStatus, code SkillStatusCode) bool {
	for _, s := range statuses {
		if s.Status == code {
			return true
		}
	}
	return false
}

package skills

import (
	"strings"
	"testing"
)

func TestParseSkillValidDocument(t *testing.T) {
	raw := strings.Join([]string{
		"---",
		"name: dogfood",
		"description: Systematic exploratory QA testing",
		"version: 1.0.0",
		"metadata:",
		"  hermes:",
		"    tags: [qa, testing]",
		"---",
		"",
		"# Dogfood",
		"",
		"Follow the workflow carefully.",
		"",
	}, "\n")

	skill, err := Parse([]byte(raw), 8*1024)
	if err != nil {
		t.Fatalf("Parse returned error: %v", err)
	}
	if skill.Name != "dogfood" {
		t.Fatalf("Name = %q, want %q", skill.Name, "dogfood")
	}
	if skill.Description != "Systematic exploratory QA testing" {
		t.Fatalf("Description = %q", skill.Description)
	}
	if !strings.Contains(skill.Body, "# Dogfood") {
		t.Fatalf("Body = %q, want markdown heading", skill.Body)
	}
}

func TestOptionalSkillCatalogHermesV014Metadata(t *testing.T) {
	raw := strings.Join([]string{
		"---",
		"name: osint-investigation",
		"description: Public-records OSINT investigation framework",
		"version: 0.1.0",
		"platforms: [linux, macos, windows]",
		"metadata:",
		"  hermes:",
		"    tags: [osint, investigation, public-records]",
		"    category: research",
		"    homepage: https://developers.notion.com",
		"    related_skills: [domain-intel, arxiv]",
		"---",
		"",
		"# OSINT Investigation",
		"",
		"Use public records only.",
		"",
	}, "\n")

	skill, err := Parse([]byte(raw), 8*1024)
	if err != nil {
		t.Fatalf("Parse returned error: %v", err)
	}
	if skill.HermesCategory != "research" {
		t.Fatalf("HermesCategory = %q, want research", skill.HermesCategory)
	}
	if skill.HermesHomepage != "https://developers.notion.com" {
		t.Fatalf("HermesHomepage = %q, want Notion homepage", skill.HermesHomepage)
	}
	if strings.Join(skill.RelatedSkills, ",") != "domain-intel,arxiv" {
		t.Fatalf("RelatedSkills = %v, want domain-intel/arxiv", skill.RelatedSkills)
	}
}

func TestParseSkillRejectsMissingRequiredHeaderFields(t *testing.T) {
	tests := []struct {
		name string
		raw  string
		want string
	}{
		{
			name: "missing name",
			raw: strings.Join([]string{
				"---",
				"description: Missing a name",
				"---",
				"",
				"body",
				"",
			}, "\n"),
			want: "name",
		},
		{
			name: "missing description",
			raw: strings.Join([]string{
				"---",
				"name: nameless-doc",
				"---",
				"",
				"body",
				"",
			}, "\n"),
			want: "description",
		},
	}

	for _, tc := range tests {
		t.Run(tc.name, func(t *testing.T) {
			_, err := Parse([]byte(tc.raw), 8*1024)
			if err == nil {
				t.Fatal("Parse returned nil error, want failure")
			}
			if !strings.Contains(err.Error(), tc.want) {
				t.Fatalf("error = %q, want mention of %q", err, tc.want)
			}
		})
	}
}

package skills

import (
	"strings"
	"testing"
)

func TestSkillFrontmatterValidation_MissingOpenAndClose(t *testing.T) {
	t.Run("missing open emits MISSING_OPEN at first non-empty line", func(t *testing.T) {
		raw := strings.Join([]string{
			"",
			"",
			"# Heading without frontmatter",
			"",
			"body",
		}, "\n")

		errs := ValidateSkillFrontmatter([]byte(raw), FrontmatterValidateOptions{})

		if got := codeOf(errs, SkillValidationMissingOpen); got == nil {
			t.Fatalf("errors = %+v, want a MISSING_OPEN entry", errs)
		} else if got.Line != 3 {
			t.Fatalf("MISSING_OPEN.Line = %d, want 3 (first non-empty)", got.Line)
		}

		if codeOf(errs, SkillValidationMissingClose) != nil {
			t.Fatalf("errors = %+v, want no MISSING_CLOSE when MISSING_OPEN already fired", errs)
		}
	})

	t.Run("empty file emits MISSING_OPEN", func(t *testing.T) {
		errs := ValidateSkillFrontmatter([]byte("\n\n"), FrontmatterValidateOptions{})
		if codeOf(errs, SkillValidationMissingOpen) == nil {
			t.Fatalf("errors = %+v, want MISSING_OPEN for empty file", errs)
		}
	})

	t.Run("body heading before close emits MISSING_CLOSE", func(t *testing.T) {
		raw := strings.Join([]string{
			"---",
			"name: half-frontmatter",
			"# Heading without close",
			"",
			"body",
		}, "\n")

		errs := ValidateSkillFrontmatter([]byte(raw), FrontmatterValidateOptions{})

		got := codeOf(errs, SkillValidationMissingClose)
		if got == nil {
			t.Fatalf("errors = %+v, want a MISSING_CLOSE entry", errs)
		}
		if got.Line != 3 {
			t.Fatalf("MISSING_CLOSE.Line = %d, want 3 (heading line)", got.Line)
		}
	})
}

func TestSkillFrontmatterValidation_EmptyAndYAMLParse(t *testing.T) {
	t.Run("empty frontmatter block", func(t *testing.T) {
		raw := strings.Join([]string{
			"---",
			"---",
			"",
			"body",
		}, "\n")

		errs := ValidateSkillFrontmatter([]byte(raw), FrontmatterValidateOptions{})
		if codeOf(errs, SkillValidationEmptyFrontmatter) == nil {
			t.Fatalf("errors = %+v, want EMPTY_FRONTMATTER", errs)
		}
	})

	t.Run("malformed YAML emits YAML_PARSE", func(t *testing.T) {
		raw := strings.Join([]string{
			"---",
			"name: broken",
			"description: [unterminated",
			"---",
			"",
			"body",
		}, "\n")

		errs := ValidateSkillFrontmatter([]byte(raw), FrontmatterValidateOptions{})
		if codeOf(errs, SkillValidationYAMLParse) == nil {
			t.Fatalf("errors = %+v, want YAML_PARSE for unterminated value", errs)
		}
	})
}

func TestSkillFrontmatterValidation_NullBytesAndNestedQuotes(t *testing.T) {
	t.Run("null bytes record line evidence", func(t *testing.T) {
		raw := "---\nname: tainted\n\x00garbage\n---\n\nbody"

		errs := ValidateSkillFrontmatter([]byte(raw), FrontmatterValidateOptions{})

		got := codeOf(errs, SkillValidationNullBytes)
		if got == nil {
			t.Fatalf("errors = %+v, want NULL_BYTES", errs)
		}
		if got.Line != 3 {
			t.Fatalf("NULL_BYTES.Line = %d, want 3 (line containing the null byte)", got.Line)
		}
	})

	t.Run("nested double quotes in scalar value", func(t *testing.T) {
		raw := strings.Join([]string{
			"---",
			"name: nicknamer",
			`description: "Phil "Nick" Last"`,
			"---",
			"",
			"body",
		}, "\n")

		errs := ValidateSkillFrontmatter([]byte(raw), FrontmatterValidateOptions{})
		got := codeOf(errs, SkillValidationNestedQuotes)
		if got == nil {
			t.Fatalf("errors = %+v, want NESTED_QUOTES", errs)
		}
		if got.Line != 3 {
			t.Fatalf("NESTED_QUOTES.Line = %d, want 3 (description line)", got.Line)
		}
	})
}

func TestSkillFrontmatterValidation_SlugMismatch(t *testing.T) {
	raw := strings.Join([]string{
		"---",
		"name: review-tests",
		"description: Slug differs from path",
		"slug: not-the-directory",
		"---",
		"",
		"body",
	}, "\n")

	t.Run("declared slug differs from expected", func(t *testing.T) {
		errs := ValidateSkillFrontmatter([]byte(raw), FrontmatterValidateOptions{ExpectedSlug: "review-tests"})
		if codeOf(errs, SkillValidationSlugMismatch) == nil {
			t.Fatalf("errors = %+v, want SLUG_MISMATCH", errs)
		}
	})

	t.Run("declared slug matches expected", func(t *testing.T) {
		matching := strings.ReplaceAll(raw, "not-the-directory", "review-tests")
		errs := ValidateSkillFrontmatter([]byte(matching), FrontmatterValidateOptions{ExpectedSlug: "review-tests"})
		if codeOf(errs, SkillValidationSlugMismatch) != nil {
			t.Fatalf("errors = %+v, want no SLUG_MISMATCH when slugs match", errs)
		}
	})

	t.Run("missing expected slug skips check", func(t *testing.T) {
		errs := ValidateSkillFrontmatter([]byte(raw), FrontmatterValidateOptions{})
		if codeOf(errs, SkillValidationSlugMismatch) != nil {
			t.Fatalf("errors = %+v, want no SLUG_MISMATCH when ExpectedSlug is empty", errs)
		}
	})
}

func TestSkillFrontmatterValidation_ValidDocumentReportsNoErrors(t *testing.T) {
	raw := strings.Join([]string{
		"---",
		"name: clean",
		"description: A valid skill",
		"---",
		"",
		"body",
	}, "\n")

	errs := ValidateSkillFrontmatter([]byte(raw), FrontmatterValidateOptions{ExpectedSlug: "clean"})
	if len(errs) != 0 {
		t.Fatalf("errors = %+v, want none for a clean document", errs)
	}
}

func codeOf(errs []SkillValidationError, code SkillValidationCode) *SkillValidationError {
	for i := range errs {
		if errs[i].Code == code {
			return &errs[i]
		}
	}
	return nil
}

